old_render_table = "function renderTable(a){$('clist').className='tableWrap';$('clist').innerHTML=`<table class=\"contactTable\"><thead><tr><th>Name</th><th>Type</th><th>BGG ID</th><th>Email</th><th>BGG User</th><th>First Contact</th><th>Heard Back</th><th>Source Game</th><th>Notes</th></tr></thead><tbody>${a.map(c=>editRow(c)).join('')}</tbody></table>`;document.querySelectorAll('[data-auto-row]').forEach(x=>{x.onchange=()=>autoSaveRow(+x.dataset.autoRow,x);if(x.type==='text')x.onblur=()=>autoSaveRow(+x.dataset.autoRow,x)})}"
