new_edit_row = "function editRow(c){return `<tr><td><b>${e(c.name)}</b></td><td>${e(c.bgg_type.replace('boardgame',''))}</td><td>${e(c.bgg_id)}</td><td><input data-auto-row=\"${c.id}\" id=\"re-org-${c.id}\" value=\"${e(c.organization||'')}\"></td><td><input data-auto-row=\"${c.id}\" id=\"re-email-${c.id}\" type=\"email\" value=\"${e(c.email||'')}\"></td><td><input data-auto-row=\"${c.id}\" id=\"re-bgg-${c.id}\" value=\"${e(c.bgg_username||'')}\"></td><td><input data-auto-row=\"${c.id}\" id=\"re-discord-${c.id}\" value=\"${e(c.discord_username||'')}\"></td><td><select data-auto-row=\"${c.id}\" id=\"re-preferred-${c.id}\">${preferredOptions(c.preferred_contact_method||'')}</select></td><td><input data-auto-row=\"${c.id}\" id=\"re-date-${c.id}\" type=\"date\" value=\"${e(c.first_contact_date||'')}\"></td><td><button id=\"re-heard-${c.id}\" class=\"btn smallBtn ${c.heard_back?'yesBtn':'noBtn'}\" data-heard=\"${c.heard_back?'1':'0'}\" onclick=\"toggleRowHeard(${c.id})\">${c.heard_back?'Yes':'No'}</button></td><td><input data-auto-row=\"${c.id}\" class=\"wideInput\" id=\"re-source-${c.id}\" value=\"${e(c.source_game_name||'')}\"></td><td><input data-auto-row=\"${c.id}\" class=\"notesInput\" id=\"re-notes-${c.id}\" value=\"${e(c.notes||'')}\"></td></tr>`}"
