old_save_row = "async function saveRow(id){let data={email:$('re-email-'+id).value.trim()||null,bgg_username:$('re-bgg-'+id).value.trim()||null,first_contact_date:$('re-date-'+id).value||null,heard_back:$('re-heard-'+id).dataset.heard==='1',source_game_name:$('re-source-'+id).value.trim()||null,notes:$('re-notes-'+id).value.trim()||null,updated_at:new Date().toISOString()};await dbApi('bg_contact','UPDATE',{filters:{id},data});let c=contacts.find(x=>x.id===id);if(c)Object.assign(c,data)}"
new_save_row = "async function saveRow(id){let data={organization:$('re-org-'+id).value.trim()||null,email:$('re-email-'+id).value.trim()||null,bgg_username:$('re-bgg-'+id).value.trim()||null,discord_username:$('re-discord-'+id).value.trim()||null,preferred_contact_method:$('re-preferred-'+id).value||null,first_contact_date:$('re-date-'+id).value||null,heard_back:$('re-heard-'+id).dataset.heard==='1',source_game_name:$('re-source-'+id).value.trim()||null,notes:$('re-notes-'+id).value.trim()||null,updated_at:new Date().toISOString()};await dbApi('bg_contact','UPDATE',{filters:{id},data});let c=contacts.find(x=>x.id===id);if(c)Object.assign(c,data)}"
