# 8) Card view: surface the communication channels at a glance.
old_cards = "function renderCards(a){$('clist').className='contacts';$('clist').innerHTML=a.map(c=>`<article class=\"card contact\" data-c=\"${c.id}\"><div class=\"contactTitle\">${e(c.name)}</div><span class=\"contactType\">${e(c.bgg_type.replace('boardgame',''))}</span> <span class=\"replyTag ${c.heard_back?'replyYes':'replyNo'}\">${c.heard_back?'Replied':'No Reply'}</span><div class=\"meta\">BGG ID ${c.bgg_id}</div>${c.email?`<div class=\"contactDetail\">✉ ${e(c.email)}</div>`:''}${c.bgg_username?`<div class=\"contactDetail\">BGG: ${e(c.bgg_username)}</div>`:''}${c.first_contact_date?`<div class=\"contactDetail\">First contact: ${e(c.first_contact_date)}</div>`:''}${c.source_game_name?`<div class=\"meta\">Source: ${e(c.source_game_name)}</div>`:''}</article>`).join('');document.querySelectorAll('[data-c]').forEach(x=>x.onclick=()=>openContact(+x.dataset.c))}"
new_cards = "function renderCards(a){$('clist').className='contacts';$('clist').innerHTML=a.map(c=>`<article class=\"card contact\" data-c=\"${c.id}\"><div class=\"contactTitle\">${e(c.name)}${c.preferred_contact_method?`<span class=\"preferredTag\">${e(c.preferred_contact_method)}</span>`:''}</div>${c.organization?`<div class=\"meta\">${e(c.organization)}</div>`:''}<span class=\"contactType\">${e(c.bgg_type.replace('boardgame',''))}</span> <span class=\"replyTag ${c.heard_back?'replyYes':'replyNo'}\">${c.heard_back?'Replied':'No Reply'}</span><div class=\"meta\">BGG ID ${c.bgg_id}</div>${c.email?`<div class=\"contactDetail\">✉ ${e(c.email)}</div>`:''}${c.bgg_username?`<div class=\"contactDetail\">BGG: ${e(c.bgg_username)}</div>`:''}${c.discord_username?`<div class=\"contactDetail discord\">Discord: ${e(c.discord_username)}</div>`:''}${c.first_contact_date?`<div class=\"contactDetail\">First contact: ${e(c.first_contact_date)}</div>`:''}${c.source_game_name?`<div class=\"meta\">Source: ${e(c.source_game_name)}</div>`:''}${c.notes?`<div class=\"contactNote\">${e(c.notes)}</div>`:''}</article>`).join('');document.querySelectorAll('[data-c]').forEach(x=>x.onclick=()=>openContact(+x.dataset.c))}"
replace_once(old_cards, new_cards, "contact cards")

# 9) Drawer behavior for edit and create.
old_open_contact = "function setModalHeard(v){modalHeard=!!v;$('heardYes').className='btn '+(modalHeard?'yesBtn':'');$('heardNo').className='btn '+(!modalHeard?'noBtn':'')}function openContact(id){editContact=contacts.find(c=>c.id===id);if(!editContact)return;$('ctitle').textContent=editContact.name;$('cmeta').textContent=editContact.bgg_type.replace('boardgame','')+' • BGG ID '+editContact.bgg_id;$('editDate').value=editContact.first_contact_date||'';$('editEmail').value=editContact.email||'';$('editBgg').value=editContact.bgg_username||'';$('editSource').value=editContact.source_game_name||'';$('editNotes').value=editContact.notes||'';setModalHeard(editContact.heard_back);$('contactModal').classList.add('open')}"
new_open_contact = "function setModalHeard(v){modalHeard=!!v;$('heardYes').className='btn '+(modalHeard?'yesBtn':'');$('heardNo').className='btn '+(!modalHeard?'noBtn':'')}function fillContactForm(c){$('editName').value=c.name||'';$('editOrganization').value=c.organization||'';$('editDate').value=c.first_contact_date||'';$('editEmail').value=c.email||'';$('editBgg').value=c.bgg_username||'';$('editDiscord').value=c.discord_username||'';$('editPreferred').value=c.preferred_contact_method||'';$('editSource').value=c.source_game_name||'';$('editNotes').value=c.notes||'';setModalHeard(c.heard_back)}function openContact(id){editContact=contacts.find(c=>c.id===id);draftContact=null;if(!editContact)return;$('ctitle').textContent='Edit Contact';$('cmeta').textContent=editContact.bgg_type.replace('boardgame','')+' • BGG ID '+editContact.bgg_id;$('contactFormHint').textContent='Update any contact channel here. Changes are saved to the existing BGG-linked contact.';fillContactForm(editContact);$('deleteContact').classList.remove('hidden');$('saveContact').textContent='Save Changes';$('contactModal').classList.add('open')}function openNewContact(p,g){editContact=null;draftContact={bgg_type:p.type,bgg_id:+p.id,name:p.name,source_game_id:g?+g.id:null,source_game_name:g?.title||'',heard_back:false};$('ctitle').textContent='Add Contact';$('cmeta').textContent=p.type.replace('boardgame','')+' • BGG ID '+p.id;$('contactFormHint').textContent='Add email, BGG username or Discord now so you do not need a second edit step.';fillContactForm(draftContact);$('deleteContact').classList.add('hidden');$('saveContact').textContent='Add Contact';$('contactModal').classList.add('open')}"
replace_once(old_open_contact, new_open_contact, "contact drawer behavior")

# 10) CREATE or UPDATE from one save button.
old_save_contact = "$('saveContact').onclick=async()=>{await dbApi('bg_contact','UPDATE',{filters:{id:editContact.id},data:{first_contact_date:$('editDate').value||null,email:$('editEmail').value.trim()||null,bgg_username:$('editBgg').value.trim()||null,source_game_name:$('editSource').value.trim()||null,heard_back:modalHeard,notes:$('editNotes').value.trim()||null,updated_at:new Date().toISOString()}});await loadContacts();closeM('contactModal')}"
new_save_contact = "$('saveContact').onclick=async()=>{let name=$('editName').value.trim();if(!name){alert('Name is required');$('editName').focus();return}let data={name,organization:$('editOrganization').value.trim()||null,first_contact_date:$('editDate').value||null,email:$('editEmail').value.trim()||null,bgg_username:$('editBgg').value.trim()||null,discord_username:$('editDiscord').value.trim()||null,preferred_contact_method:$('editPreferred').value||null,source_game_name:$('editSource').value.trim()||null,heard_back:modalHeard,notes:$('editNotes').value.trim()||null,updated_at:new Date().toISOString()};$('saveContact').disabled=true;try{if(editContact){await dbApi('bg_contact','UPDATE',{filters:{id:editContact.id},data})}else if(draftContact){await dbApi('bg_contact','CREATE',{data:{...data,bgg_type:draftContact.bgg_type,bgg_id:draftContact.bgg_id,source_game_id:draftContact.source_game_id}})}await loadContacts();closeM('contactModal');if(contactReturnGameId){let id=contactReturnGameId;contactReturnGameId=null;openGame(String(id))}}finally{$('saveContact').disabled=false}}"
replace_once(old_save_contact, new_save_contact, "contact create/update save")

# Delete only applies to an existing contact and should not leave stale return state.
old_delete = "$('deleteContact').onclick=async()=>{if(editContact&&confirm('Delete '+editContact.name+'?')){await dbApi('bg_contact','DELETE',{filters:{id:editContact.id}});await loadContacts();closeM('contactModal')}}"
new_delete = "$('deleteContact').onclick=async()=>{if(editContact&&confirm('Delete '+editContact.name+'?')){await dbApi('bg_contact','DELETE',{filters:{id:editContact.id}});await loadContacts();closeM('contactModal');if(contactReturnGameId){let id=contactReturnGameId;contactReturnGameId=null;openGame(String(id))}}}"
replace_once(old_delete, new_delete, "contact delete return")

